export const sections = [
  {id:'overview', title:'Project overview', ar:'تعريف المشروع', detail:'المشروع والأطراف ونطاق التعيين'},
  {id:'governance', title:'Governance & responsibilities', ar:'الأدوار والمسؤوليات', detail:'مسؤوليات الأطراف ومصفوفة التنسيق'},
  {id:'uses', title:'BIM objectives & uses', ar:'أهداف واستخدامات BIM', detail:'الاستخدامات المرتبطة بالنطاق المختار'},
  {id:'information', title:'Information management', ar:'إدارة المعلومات', detail:'المشاركة والمراجعة وضبط الإصدارات'},
  {id:'coordination', title:'Model coordination & quality', ar:'التنسيق وضبط الجودة', detail:'مرجعية الموديلات وإدارة الملاحظات'},
  {id:'delivery', title:'Information delivery plan', ar:'خطة تسليم المعلومات', detail:'المخرجات والمسؤوليات وتوقيت التسليم'},
  {id:'fourD', title:'4D construction planning', ar:'التخطيط الزمني 4D', detail:'اختياري · يحدّث الجداول المرتبطة'},
  {id:'handover', title:'As-built & handover', ar:'As-built والتسليم', detail:'التحقق الموقعي ومتطلبات الإغلاق'},
];
export const fieldNames = ['project','code','description','location','contractor','client','consultant','documentCode','revision','date','preparedBy','software','cde'];
export const requiredFields = ['project','code','description','contractor','client','consultant','documentCode'];
export function freshState(){return {version:1,fields:Object.fromEntries(fieldNames.map(k=>[k,k==='revision'?'P01':''])),enabled:Object.fromEntries(sections.map(s=>[s.id,true])),notes:Object.fromEntries(sections.map(s=>[s.id,''])),style:{accent:'#164d75',font:'sans',cover:true,toc:true}};}
export function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
export function validateState(raw){
  if(!raw||raw.version!==1||!raw.fields||!raw.enabled||!raw.notes||!raw.style)throw new Error('ملف غير متوافق مع هذه النسخة.');
  const next=freshState();
  for(const k of fieldNames){if(typeof raw.fields[k]!=='string'||raw.fields[k].length>(k==='description'?3000:200))throw new Error('بيانات مشروع غير صالحة.');next.fields[k]=raw.fields[k];}
  if(next.fields.date&&!/^\d{4}-\d{2}-\d{2}$/.test(next.fields.date))throw new Error('تاريخ غير صالح.');
  for(const s of sections){if(typeof raw.enabled[s.id]!=='boolean'||typeof raw.notes[s.id]!=='string'||raw.notes[s.id].length>4000)throw new Error('بيانات أقسام غير صالحة.');next.enabled[s.id]=raw.enabled[s.id];next.notes[s.id]=raw.notes[s.id];}
  if(!/^#[0-9a-f]{6}$/i.test(raw.style.accent)||!['sans','serif'].includes(raw.style.font)||typeof raw.style.cover!=='boolean'||typeof raw.style.toc!=='boolean')throw new Error('إعدادات مظهر غير صالحة.');
  next.style={accent:raw.style.accent,font:raw.style.font,cover:raw.style.cover,toc:raw.style.toc};return next;
}
function table(headers,rows,cls=''){return `<table class="${cls}"><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function keyValues(rows){return `<table class="key-value"><tbody>${rows.map(([k,v])=>`<tr><th scope="row">${k}</th><td>${v}</td></tr>`).join('')}</tbody></table>`;}
export function buildDocument(state){
  const f=state.fields,e=state.enabled;
  const value=(key,label)=>escapeHtml(f[key].trim()||`[${label}]`);
  const contractor=value('contractor','Main contractor'),client=value('client','Client / Employer'),consultant=value('consultant','Supervision consultant'),project=value('project','Project name');
  const code=value('code','Project code'),docCode=value('documentCode','Document number'),revision=value('revision','Revision'),date=value('date','Issue date');
  const active=sections.filter(s=>e[s.id]);
  const responsibilityRows=[['Maintain this BEP','R','C','A'],['Produce discipline information','R','C','I'],['Check information before sharing','R','I','I'],['Review submitted information','C','R','A']];
  if(e.information)responsibilityRows.push(['Agree information exchange procedures','R','C','A']);
  if(e.coordination)responsibilityRows.push(['Coordinate models and track issues','R','C','I']);
  if(e.delivery)responsibilityRows.push(['Maintain the information delivery plan','R','C','I']);
  if(e.fourD)responsibilityRows.push(['Prepare and review 4D outputs','R','C','A']);
  if(e.handover)responsibilityRows.push(['Consolidate as-built information','R','C','A']);
  const usesRows=[];
  if(e.coordination)usesRows.push(['Construction coordination','Review interfaces and manage coordination issues.','Coordinated model and issue record']);
  if(e.information)usesRows.push(['Controlled information exchange','Share reviewed information with an identifiable purpose and revision.','Traceable information exchanges']);
  if(e.delivery)usesRows.push(['Information delivery planning','Identify deliverables, responsible parties and agreed dates.','Project delivery schedule']);
  if(e.fourD)usesRows.push(['4D construction planning','Link selected model content to the agreed programme.','Sequence review and agreed 4D outputs']);
  if(e.handover)usesRows.push(['Record information','Consolidate verified as-constructed records.','Agreed handover information']);
  const deliveryRows=[['BEP and revision record',contractor,'Mobilization and agreed changes','PDF'],['Project team responsibility schedule',contractor,'Mobilization; update on changes','Agreed project format'],['Model register and breakdown',contractor,'Before initial model exchange','Agreed project format'],['Coordinates and reference record',contractor,'Before initial model exchange','Agreed project format'],['Discipline models','Relevant production team','Dates to be agreed','Native / agreed exchange format']];
  if(e.information)deliveryRows.push(['Information exchange procedure',contractor,'Before initial exchange','Agreed project format'],['Submission register',contractor,'Each formal submission','Agreed project format']);
  if(e.coordination)deliveryRows.push(['Federated coordination model',contractor,'Agreed coordination cycle','Agreed coordination format'],['Coordination issue report',contractor,'Agreed coordination cycle','Agreed project format'],['Model quality checklist','Relevant production team','Before sharing / submission','Agreed project format']);
  deliveryRows.push(['Shop drawing packages','Relevant production team','Dates to be agreed','PDF / agreed native format']);
  if(e.fourD)deliveryRows.push(['4D sequence and review package',contractor,'Agreed planning review cycle','Agreed native format / video']);
  if(e.handover)deliveryRows.push(['As-built models and drawings',contractor,'Agreed handover milestones','Agreed native / open formats'],['Asset information, where required','Relevant supplier / production team','Agreed handover milestones','Schema to be agreed'],['Handover index and acceptance record',contractor,'Closeout','Agreed project format']);
  const bodies={
    overview:`<p>This Post-Contract BIM Execution Plan describes the proposed information production and coordination approach for <strong>${project}</strong>. It is prepared by <strong>${contractor}</strong> for review by <strong>${consultant}</strong> and agreement with <strong>${client}</strong>.</p>${keyValues([['Project',project],['Project reference',code],['Location',value('location','Project location')],['Main contractor',contractor],['Client / Employer',client],['Supervision consultant',consultant],['Appointment stage','Post-contract'],['Prepared by',value('preparedBy','Name / role')]])}<h3>Scope of works</h3><p>${value('description','Describe the appointed works and the extent of information production and coordination.')}</p><p>The extent of design responsibility, information management duties and interfaces with other appointments must be confirmed against the project appointment. The main contractor designation does not, by itself, establish those responsibilities.</p>`,
    governance:`<p>${contractor} will identify the responsible production teams and maintain clear interfaces with ${consultant} and ${client}. Each production team remains responsible for checking the information it produces within its appointed scope.</p><h3>Proposed responsibility allocation</h3><p>The allocation below is a starting point for project agreement. Review, authorization and acceptance responsibilities must be confirmed against the appointment.</p>${table(['Activity',contractor,consultant,client],responsibilityRows,'raci')}<p><strong>R</strong> — Responsible &nbsp; <strong>A</strong> — Accountable &nbsp; <strong>C</strong> — Consulted &nbsp; <strong>I</strong> — Informed.</p><h3>Decisions and changes</h3><p>Changes to scope, responsibilities and agreed procedures should be recorded with their source, owner and effective revision. Requirements that remain undecided must be tracked to resolution.</p>`,
    uses:`<p>The uses below reflect the sections selected for this draft. Their scope, responsible parties and acceptance criteria are to be agreed for ${project}.</p>${usesRows.length?table(['BIM use','Purpose','Expected result'],usesRows):'<p>No linked BIM uses have been selected. Confirm the required uses before issue.</p>'}<p>Additional analysis or operational services are included only when expressly defined in the project requirements. Selection in this draft does not constitute client acceptance.</p>`,
    information:`<p>The agreed common data environment for ${project} is <strong>${value('cde','CDE platform to be agreed')}</strong>. ${contractor} will coordinate information exchanges within its appointed scope, using the agreed access rights and review process.</p><h3>Information states and review</h3>${table(['State','Intended use','Control to define'],[['Work in progress','Information being developed by its producing team.','Internal access and checking responsibilities'],['Shared','Information released for a stated coordination or review purpose.','Readiness checks, revision and permitted use'],['Published','Information authorized for its stated project purpose.','Authorization and acceptance route'],['Archive','Retained history of information exchanges and decisions.','Retention, access and retrieval procedures']])}<p>The states above describe a proposed information workflow. Project folder names, suitability codes and consultant response codes must be mapped separately; no client-specific coding system is assumed.</p><h3>Records and security</h3><p>Record the originator, revision, issue date and intended use of each exchange. Access, retention, backup and restoration arrangements must be defined for the project. Data ownership and reuse remain subject to the applicable appointment documents.</p>`,
    coordination:`<p>Model authoring will use <strong>${value('software','Authoring software and agreed version')}</strong>. ${contractor} will establish the coordination reference, model breakdown and exchange settings with the relevant production teams.</p><h3>Common reference</h3><ul><li>Confirm the horizontal coordinate system, vertical datum, units and reference model before initial exchange.</li><li>Record the provider, revision and status of the agreed reference information.</li><li>Check model alignment, levels and grids before incorporating a new or revised model into the federation.</li></ul><h3>Coordination and quality checks</h3><p>Define clash tests by model scope and element groups, distinguishing physical intersections from clearance requirements. Tolerances, units, exclusions and priorities must be agreed for the project; no numerical tolerance is assumed in this template.</p><ul><li>Check model naming, required properties, scope and exchange format.</li><li>Review coordination results and assign genuine issues to a responsible party.</li><li>Record the reason and authority for accepted intersections or exclusions.</li><li>Verify issue closure against updated information before reporting it as resolved.</li></ul><p>Agree the coordination cycle and reporting format with ${consultant}. Technical design decisions are referred to the party with the relevant design responsibility.</p>`,
    delivery:`<p>${contractor} will consolidate the task teams’ information delivery plans into the agreed project delivery plan. The register below is a starter schedule: confirm applicability, exact dates, formats and acceptance criteria with ${consultant} and ${client}.</p>${table(['Information deliverable','Proposed producer','Timing / trigger','Format'],deliveryRows)}<p>Deliverables shown here are proposed planning entries. Replace indicative triggers with the approved dates and identify the applicable task team for each package before issue.</p>`,
    fourD:`<p>4D planning for ${project} will support review of agreed construction sequences. ${contractor} will coordinate the model linkage with the planning team and submit the agreed outputs for review by ${consultant}.</p><h3>Required project decisions</h3>${keyValues([['Programme source','[Approved programme and revision]'],['Planning tool','[Selected product and version]'],['Linking method','[Activity identifiers / selection rules]'],['Update cycle','[Agreed frequency and milestones]'],['Submission package','[Agreed native file, video and review record]']])}<h3>Working procedure</h3><ol><li>Confirm the programme revision and model scope used for each update.</li><li>Link the selected model content to programme activities using a documented method.</li><li>Review sequence logic and key interfaces with the construction and planning teams.</li><li>Record comments, revise the linkage where required and issue the agreed package.</li></ol><p>The simulation supports planning review. The applicable programme and the agreed project procedures govern its use.</p>`,
    handover:`<p>${contractor} will consolidate as-built information for ${project} from verified construction records and the relevant production teams. The required scope, accuracy, formats and acceptance criteria are to be confirmed with ${client} and ${consultant}.</p><h3>Controlled inputs</h3><ul><li>Approved drawings, requests for information and recorded site changes.</li><li>Verified red-line records and agreed field verification evidence.</li><li>Supplier and commissioning information within the appointed scope.</li></ul><h3>Verification and acceptance</h3><p>Confirm that the submitted models and records reflect the verified condition to the agreed information requirements. Identify outstanding items and the party responsible for closure. Do not assume a particular LOD, survey technology or verification tolerance without a project requirement.</p><h3>Asset information</h3><p>Where asset information is required, confirm its schema, required properties, ownership and validation procedure. COBie is one possible exchange format and is not automatically required by this template.</p>`
  };
  const cover=state.style.cover?`<div class="cover"><div class="cover-top"><span class="document-kicker">PROJECT INFORMATION DELIVERY</span><span class="draft-label">WORKING DRAFT</span></div><h1>BIM<br><b>Execution</b><br>Plan.</h1><p class="cover-subtitle">Post-Contract / Main Contractor</p><div class="cover-rule"></div><h2>${project}</h2><p class="cover-location">${code} · ${value('location','Location')}</p><dl class="cover-parties"><div><dt>Prepared for</dt><dd>${client}</dd></div><div><dt>Supervision consultant</dt><dd>${consultant}</dd></div><div><dt>Prepared by / Main contractor</dt><dd>${contractor}</dd></div></dl><dl class="cover-meta"><div><dt>Document reference</dt><dd>${docCode}</dd></div><div><dt>Revision</dt><dd>${revision}</dd></div><div><dt>Issue date</dt><dd>${date}</dd></div></dl><div class="cover-bottom"><span>PROJECT-SPECIFIC REVIEW REQUIRED</span><span>POST-CONTRACT BEP</span></div></div>`:'';
  const toc=state.style.toc?`<nav class="toc-block" aria-label="Document contents"><span class="document-kicker">DOCUMENT STRUCTURE</span><h2>Contents</h2><ol>${active.map((s,i)=>`<li><a href="#section-${s.id}"><span class="toc-number">${String(i+1).padStart(2,'0')}</span>${s.title}</a></li>`).join('')}</ol></nav>`:'';
  return `${cover}<div class="document-body"><div class="running-heading"><span>${project}</span><span>${docCode} / ${revision}</span></div><p class="doc-notice"><strong>Working draft.</strong> Generic content for project adaptation. Confirm requirements, responsibilities and all bracketed entries before formal issue. This document does not assert compliance with an unreviewed client standard.</p>${toc}${active.length?active.map((s,i)=>`<section class="doc-section" id="section-${s.id}"><div class="section-number">SECTION ${String(i+1).padStart(2,'0')}</div><h2>${i+1}. ${s.title}</h2>${bodies[s.id]}${state.notes[s.id].trim()?`<div class="project-note"><strong>Project-specific note</strong>${escapeHtml(state.notes[s.id])}</div>`:''}</section>`).join(''):'<p>No sections selected. Select the required content before printing.</p>'}<footer class="doc-end"><span>${contractor}</span><span>END OF DOCUMENT · ${revision}</span></footer></div>`;
}
